/* Generated from vita/manual/manual.txt by tools/manual_gen.py. */
typedef struct { const char *title; const char *const *lines; int count; } CT_ManualSection;
static const char *const ct_manual_lines_0[]={"Outside menus and dialogs:","  Left stick: scroll the camera","  Right stick: move the mouse pointer","  Cross or R: left click (hold to drag, e.g. floors or offices)","  L: right click (hold and move to drag the camera)","  Circle: Hand (pointer/select) tool","  Triangle: Inspect (magnifying glass) tool","  Square: Bulldozer tool","  D-pad: fine pointer nudge; with a build item selected,","    one tile left/right or one floor up/down (hold to repeat)","  Front touch: tap to click, drag to drag","  Start: open or close the top menu","  Select: debug labels","In menus, dialogs and this manual:","  D-pad: move the yellow focus box","  Cross or Circle: confirm / press the focused button (OK)","  Triangle: cancel and close without confirming","Touch and the pointer also work everywhere."};
static const char *const ct_manual_lines_1[]={"1. Pick an item from the Tools window or the Build Res. / Build Com. /","   Transport / Services menus. The pointer shows a crosshair.","2. Aim with the right stick or touch; the D-pad steps exactly one tile","   or one floor at a time.","3. Press Cross (or R / tap) to place. Hold and drag to lay a row of","   floors, offices or lobby in one go.","Everything above ground needs floor under it, and each new floor must sit","on the one below. The cost shows at the bottom of the Tools window; you","cannot build without enough funds.","Bulldozer (Square) removes what you click. Circle returns to the Hand."};
static const char *const ct_manual_lines_2[]={"Tools window: Play/Pause at the top, then Bulldozer, Hand and Inspect,","then the build items. Items with a small corner triangle open a flyout","with related items (hotel rooms, food, transport and so on). New items","unlock as your tower earns stars.","Hand: the normal pointer. Double-click an elevator shaft for its settings.","Inspect: click a tenant or person to see details, rent and evaluation.","Tower Info (top right): clock, star rating, date, funds and population,","plus messages about events in your tower.","Map (left): click to jump the camera. The tabs switch between the plain","view, evaluation (blue good / yellow so-so / red bad), rent and hotel.","Drag any window by its title bar."};
static const char *const ct_manual_lines_3[]={"Top menu > Tool Sizing changes only the Tools window and its buttons:","  Original size (1x), 25% larger (default) or 50% larger.","The check mark shows the current choice. It is saved to","ux0:data/concilia-tower/prefs.cfg and kept between sessions.","If 50% does not fit with many items unlocked, the window is shrunk just","enough to stay on screen. The Map is never resized."};
static const char *const ct_manual_lines_4[]={"Game > Save writes your current slot. The default save is","ux0:data/concilia-tower/vitatower.sav.","Existing concilliatower.sav files still load, and stay the current slot","until a vitatower.sav exists. Game > Save As... lets you pick a slot","(tower-01.sav ... tower-16.sav) or overwrite an existing save. Game >","Load lists every .sav file in ux0:data/concilia-tower/.","Game > New Tower asks if you want to save first: Yes opens Save As","(then opens New Construction after a successful save); No opens","New Construction without saving; Cancel keeps the current tower.","New Construction sets the tower name (default Vita Tower) and","architect. Build Tower starts the new tower; Cancel keeps the","current one. The tower name appears on Tower Info and becomes the","default save file (spaces become underscores, e.g. Vita_Tower.sav).","Each save keeps three older backups (.1 .2 .3). Export .TDT writes an","original-format tower file that other SimTower versions can open.","Saves and boot.log stay in ux0:data/concilia-tower/ for all versions."};
static const char *const ct_manual_lines_5[]={"Start with a lobby on the ground floor; everything is reached through it.","Add floors, then offices: office workers pay rent and are your first income.","Condos sell once for a big payment. Fast food and shops feed and entertain","people. Hotel rooms need housekeeping and earn money each night.","Elevators: place a shaft, then drag its top or bottom to extend it. A shaft","serves at most 30 floors; express elevators skip floors and stop only at","lobbies (sky lobbies every 15 floors). Stairs and escalators work for","short trips. Long waits make tenants unhappy and they will move out.","Evaluation: use the Map's Eval tab or Inspect. Red tenants are unhappy -","fix transport, noise or missing services nearby.","Stars: grow the population and add the required facilities (security,","medical center, recycling, metro, ...) to earn stars. More stars unlock","more items. Watch for fires and bomb threats; security helps.","Speed: Play/Pause in Tools or the Speed menu."};
static const CT_ManualSection ct_manual[]={{"Controls",ct_manual_lines_0,18},{"Building",ct_manual_lines_1,10},{"Tools and Tower Info",ct_manual_lines_2,11},{"Tool Sizing",ct_manual_lines_3,6},{"Saving and loading",ct_manual_lines_4,16},{"Playing Vita Tower",ct_manual_lines_5,14}};
